final class ConfigurableClock implements Clock {
    private Instant now;
    private RuntimeException failure;

    ConfigurableClock withNow(Instant value) { this.now = value; return this; }
    ConfigurableClock failingWith(RuntimeException e) { this.failure = e; return this; }

    @Override public Instant now() {
        if (failure != null) throw failure;
        return now;
    }
}

